import { render } from '@testing-library/react'
import type { ReactElement } from 'react'
import { StrictMode } from 'react'
import { MemoryRouter } from 'react-router-dom'
import { SessionProvider } from '../context/SessionProvider'
import type { AnalyticsResponse, HistoryResponse, RecommendationRun, SavedProfile } from '../types/api'
import analyticsJson from './fixtures/analytics.json'
import historyJson from './fixtures/history.json'
import profileJson from './fixtures/profile.json'
import runJson from './fixtures/run.json'

// Fixtures were generated by the real FastAPI backend (see src/test/fixtures/README.md).
export const profile: SavedProfile = profileJson as SavedProfile
export const run: RecommendationRun = runJson as RecommendationRun
export const history: HistoryResponse = historyJson as HistoryResponse
export const analytics: AnalyticsResponse = analyticsJson as AnalyticsResponse

export function seedSession(opts: { profile?: SavedProfile | null; runId?: number | null }) {
  localStorage.setItem('contribmatch.session.v1', JSON.stringify({ profile: opts.profile ?? null, runId: opts.runId ?? null }))
}

/** Renders inside StrictMode (as in main.tsx) + router + session provider. */
export function renderApp(ui: ReactElement, route = '/') {
  return render(
    <StrictMode>
      <MemoryRouter initialEntries={[route]}>
        <SessionProvider>{ui}</SessionProvider>
      </MemoryRouter>
    </StrictMode>,
  )
}
